    'يُظهر سجلّك المهني \u2068(vida laboral)\u2069 كل بدء وكل انتهاء عمل وأيام الاشتراك:',
  'result.benefit_work_history_link':
    'تقرير سجلّك المهني \u2068(informe de vida laboral)\u2069 على موقع Seguridad Social',
  'result.benefit_just_cause':
    'هناك استثناءات. ترك العمل لأحد الأسباب التالية يُعدّ وضعًا قانونيًا للبطالة \u2068(situación legal de desempleo)\u2069، ويمنح الحق في إعانة البطالة إذا استوفيت باقي الشروط: النقل إلى مكان عمل آخر \u2068(art. 40 ET)\u2069، أو تعديل جوهري لشروط عملك يضرّ بك \u2068(art. 41.3 ET)\u2069، أو إخلال جسيم من الشركة، مثل عدم دفع راتبك أو دفعه متأخرًا مرة بعد مرة \u2068(art. 50 ET)\u2069، أو العنف القائم على النوع الاجتماعي أو العنف الجنسي \u2068(art. 49.1.m ET)\u2069. ينص على ذلك art. 267.1.a.5.º LGSS. ترك العمل بموجب art. 50 تُقرّه المحكمة عادةً.',
  'result.benefit_calculation':
    'القاعدة هي متوسط ما دُفع من اشتراكات عن البطالة في الـ180 يومًا الأخيرة؛ وهنا تُستخرج من راتبك السنوي الإجمالي مع الدفعات الإضافية، مقسومًا على 12، ضمن القاعدتين الدنيا والقصوى لعام 2026. تُدفع نسبة 70 % من القاعدة في الـ180 يومًا الأولى و60 % بعدها، مع حدّ أدنى وحدّ أقصى بحسب عدد الأبناء أو البنات الذين تعولهم. تتبع المدة سُلّم art. 269.1: الـ360 يومَ اشتراك في السنوات الـ6 الأخيرة تمنح 120 يومًا من الإعانة، وكل 180 يومًا إضافية تضيف 60، حتى 720.',
  'guide.title': 'كيف تُحسب التسوية النهائية \u2068(finiquito)\u2069',
