  'legal_notice.seller_address': 'عنوانه {domicilio}.',
  'privacy.title': 'الخصوصية · eslojusto.es',
  'privacy.description':
    'ما تكتبه أثناء مراجعة تسويتك النهائية \u2068(finiquito)\u2069 لا يغادر متصفحك. لا توجد ملفات تعريف الارتباط \u2068(cookies)\u2069، وتُقاس الخطوات دون التعرّف على هويتك، باستخدام PostHog داخل الاتحاد الأوروبي.',
  'privacy.h1': 'الخصوصية',
  'privacy.summary': 'باختصار',
