    'العقد مع ملاحقه، وإن كانت لديك، قسائم راتبك أو عرض العمل أو سجلّك المهني \u2068(vida laboral)\u2069، بأي ترتيب. حتى 25 صورة أو صفحة PDF في المجموع. تتحوّل الصور وصفحات ملفات PDF إلى صور على جهازك قبل إرسالها.',
  'employment.documents.consent':
    'أمنح موافقتي الصريحة على أن يقرأ الذكاء الاصطناعي هذه المستندات ويملأ النموذج. أعلم أنها قد تتضمّن بيانات حساسة، مثل الانتساب إلى نقابة، أو إجازة مرضية \u2068(baja médica)\u2069، أو إعاقة. تُقرأ داخل الاتحاد الأوروبي ولا تُحفظ.',
  'employment.pass.title': 'التفاصيل والتقرير والرسالة',
  'employment.pass.text':
    'مقابل 4,99 € ترى الحساب خطوةً خطوة لكل نقطة في عقدك (سنةً سنة وقسيمةً قسيمة، مع النص القانوني المطبَّق ومصدره) وتنزّل التقرير بصيغة PDF، وإن كانت في مراجعتك نقاط تخصّها، الرسالة إلى الشركة. تُنشأ على جهازك.',
  'employment.pass.price':
    '4,99 € شاملًا ضريبة القيمة المضافة \u2068(IVA)\u2069. دفعة واحدة، دون حساب ولا اشتراك. يدوم التصريح 7 أيام ولا يصلح إلا في هذا المتصفح، وأيضًا لمراجعتَي التسوية النهائية \u2068(finiquito)\u2069 والإيجار: خلال تلك المدة يمكنك إعادة مراجعتك أو تصحيحها، وقراءة ما يصل إلى 15 حزمة من المستندات، والعودة إلى رؤية التفاصيل وتنزيل التقرير والرسالة دون الدفع مرة أخرى. ويضيع إذا استخدمت جهازًا آخر أو نافذة خاصة، أو إذا حذفت بيانات التصفح.',
  'employment.pass.paid_help':
    'إذا دفعت من هذا المتصفح ولا ترى التفاصيل ولا التنزيلات، استعد تصريحك من هنا. لا يعمل ذلك إلا في المتصفح الذي دفعت منه.',
  'employment.pass.waiver':
    'أريد رؤية التفاصيل والتقرير الآن. أعلم أنني، لكونه محتوى رقميًا يُسلَّم فورًا، أفقد حق العدول \u2068(derecho de desistimiento)\u2069 \u2068(art. 103.m de la Ley General para la Defensa de los Consumidores y Usuarios)\u2069.',
  'employment.pass.download_information_letter':
    'تنزيل الرسالة التي تطلب المعلومات كتابةً (PDF، مجانًا)',
  'employment.pass.download_certificate_request': 'تنزيل طلب شهادة العقود المؤقتة (PDF، مجانًا)',
  'employment.pass.download_company_letter': 'تنزيل الرسالة إلى الشركة \u2068(PDF)\u2069',
  'employment.pass.letter_note':
    'الرسائل نماذج. تُنزَّل على جهازك ولا تُرسَل من هنا: استخدامها أو عدمه، وكيفية استخدامها، قرار يعود إليك.',
  'employment.letters.title': 'رسائل يمكنك تنزيلها مجانًا',
  'employment.letters.text': 'هذه الرسائل تطلب معلومات فقط وتُنزَّل مجانًا. تُنشأ على جهازك.',
