  'rent_indices.now':
    'مع آخر IRAV \u2068({irav})\u2069 وطالما يسري {norma}، فإن الحد الأقصى دون اتفاق جديد هو {tope}: الأدنى من الاثنين. وإذا تجاوز إيجارك الحد الأقصى للسعر المطبَّق عليه وفق نظام المؤشرات المرجعية، فلا مجال لأي زيادة.',
  'rent_indices.repealed':
    'مراسيم بالحد الأقصى نفسه البالغ 2 % ألغاها البرلمان \u2068(Congreso)\u2069: {lista}. والزيادة التي تقع في تلك الأيام حالة مشكوك فيها.',
