  'rental.title':
    'زيادة الإيجار والتأمين \u2068(fianza)\u2069: راجِع ما إذا كنت تدفع أكثر من اللازم',
  'rental.description':
    'تحقّق مما إذا كانت الزيادة أو التأمين \u2068(fianza)\u2069 أو المصاريف أو الوكالة في إيجارك تتجاوز ما يسمح به القانون، بندًا بندًا ومع النص القانوني لكل منها.',
  'rental.h1': 'تحقّق مما إذا كان إيجارك عادلًا',
  'rental.lead':
    'راجِع ما تدفعه أو دفعته مقابل إيجار مسكنك مقارنةً بما يسمح به القانون: الوكالة، والتأمين \u2068(fianza)\u2069 والضمانات، والزيادات، والمصاريف، وإرجاع التأمين.',
  'rental.beta': 'تجريبي \u2068(Beta)\u2069',
