  'rental.landlord.large': 'هل المؤجِّر مالك كبير \u2068(gran tenedor)\u2069؟',
  'rental.landlord.large_hint':
    'المالك الكبير هو من يملك أكثر من عشرة عقارات حضرية للاستخدام السكني أو أكثر من 1.500 m² للاستخدام السكني، دون احتساب المرائب ولا المخازن \u2068(art. 3.k de la Ley 12/2023)\u2069؛ وفي منطقة سكنية متوترة \u2068(zona tensionada)\u2069، يمكن للمنطقة ذات الحكم الذاتي أن تخفّض ذلك إلى خمسة عقارات أو أكثر. ومنذ 08-10-2026، يضيف Real Decreto-ley 29/2026، الذي ينتظر مصادقة البرلمان \u2068(Congreso)\u2069، أن ذلك يُثبَت بشهادة من السجل العقاري \u2068(Registro de la Propiedad)\u2069، وأن كل وحدة للاستخدام السكني في مبنى تُحتسب عقارًا واحدًا، حتى لو لم يكن هناك تقسيم أفقي \u2068(división horizontal)\u2069 مسجَّل. ولا يكفي أن يكون المؤجِّر شركة: الشركة التي تملك شققًا قليلة ليست مالكًا كبيرًا.',
