  'bills.documents.consent':
    'أمنح موافقتي الصريحة على أن يقرأ الذكاء الاصطناعي هذه المستندات ويملأ النموذج. أعلم أنها قد تتضمّن بيانات شخصية، مثل الأسماء أو العناوين أو أرقام الحسابات. ومن رمز نقطة التزويد \u2068(CUPS)\u2069 لا تبقى إلا بصمة \u2068(huella)\u2069 للتعرّف على الفاتورة المكرَّرة. تُقرأ داخل الاتحاد الأوروبي ولا تُحفَظ.',
  'bills.electricity.documents.start_help':
    'يمكنك رفع فواتير الكهرباء لملء البيانات بما يُقرأ فيها، أو كتابتها بنفسك. وقبل مراجعة أي شيء، تؤكّد كل معلومة، فاتورةً فاتورة.',
  'bills.electricity.documents.upload': 'ارفع فاتورة كهرباء واحدة أو أكثر',
  'bills.electricity.documents.files_hint':
    'جميع صفحات فواتير الكهرباء، وإن كانت لديك، العقد أو إشعار بتغيير الأسعار، بأي ترتيب. حتى 25 صورة أو صفحة PDF في المجموع. تتحوّل الصور وصفحات ملفات PDF إلى صور على جهازك قبل إرسالها.',
  'bills.telecom.documents.start_help':
    'يمكنك رفع عقدك وفواتير الهاتف أو الإنترنت لملء البيانات بما يُقرأ فيها، أو كتابتها بنفسك. وقبل مراجعة أي شيء، تؤكّد كل معلومة.',
  'bills.telecom.documents.upload': 'ارفع عقدك، وإن كانت لديك، فواتير الهاتف أو الإنترنت',
  'bills.telecom.documents.files_hint':
    'العقد أو شروط فترة الالتزام فيه، وإن كانت لديك، فواتيرك: فواتير الغرامة أو ما بعد إلغاء الاشتراك، وأي فاتورة أخرى تريد مراجعة مبالغها، بأي ترتيب. حتى 25 صورة أو صفحة PDF في المجموع. تتحوّل الصور وصفحات ملفات PDF إلى صور على جهازك قبل إرسالها.',
  'bills.pass.title': 'تقرير فواتيرك والرسالة',
  'bills.pass.letter_note':
    'الرسالة نموذج. تُنزَّل على جهازك ولا تُرسَل من هنا: استخدامها أو عدمه، وكيفية استخدامها، قرار يعود إليك.',
  'bills.pass.download_correction_letter':
    'تنزيل الرسالة التي تطلب الفاتورة التصحيحية \u2068(factura rectificativa)\u2069 \u2068(PDF)\u2069',
  'bills.letter.legend': 'بياناتك للرسالة (اختياري)',
  'bills.letter.id': 'DNI أو NIE (اختياري)',
  'bills.letter.company': 'شركة تسويق الكهرباء \u2068(comercializadora)\u2069',
  'bills.letter.reference': 'رقم العقد',
  'bills.letter.privacy':
    'لا تُستخدَم هذه البيانات إلا لملء الرسالة على جهازك؛ ولا تُرسَل ولا تُحفَظ.',
  'bills.telecom.charges.title': 'ما يُحصَّل منك',
  'bills.telecom.charges.lead':
    'كل سطر قُرئ في فواتيرك، لكي تتعرّف على كل ما يُحصَّل منك. إذا رأيت شيئًا لم تتعاقد عليه بنفسك، اسأل شركتك.',
  'bills.telecom.charges.extras':
    'الأسطر الموسومة «إضافي» \u2068(Extra)\u2069 هي خدمات بأسعار إضافية \u2068(tarificación adicional)\u2069 أو خدمات من أطراف ثالثة: تُحصَّل بمعزل عن تعرفتك. إذا لم تتعاقد عليها بنفسك، اسأل شركتك.',
  'bills.telecom.charges.fees':
    'لا تذكر الفاتورة أيّ الأقساط هو قسط تعرفتك: تحقّق من أنك تتعرّف على كل قسط.',
  'bills.telecom.charges.promotions': 'خصومات تنتهي',
  'bills.telecom.charges.rights': 'ما يقوله النص القانوني',
  'bills.telecom.charges.disconnect':
    'يمكنك أن تطلب من شركتك فصل خدمات الأسعار الإضافية \u2068(tarificación adicional)\u2069 والمكالمات الدولية. ويتعيّن عليها قبول الطلب كتابةً، أو بالهاتف، أو عبر الإنترنت، وفصلها خلال 10 أيام في أقصى الأحوال؛ وإذا لم تفعل ذلك في هذه المهلة لسبب لا يعود إليك، فإن تكلفة تلك الخدمات تقع على عاتقها.',
  'bills.telecom.charges.unrequested':
    'إذا لم تطلب خدمة ما، فإن القانون لا يسمح بتحصيلها منك، وعدم الرد على من يقدّمها لا يُعدّ قبولًا لها. إذا لم تتعاقد عليها بنفسك، اسأل شركتك.',
  'bills.telecom.pass.title': 'التقرير والرسائل',
  'bills.telecom.pass.letter_note':
    'الرسائل نماذج. تُنزَّل على جهازك ولا تُرسَل من هنا: استخدامها أو عدمه، وكيفية استخدامها، قرار يعود إليك.',
  'bills.telecom.pass.download_exit_letter':
    'تنزيل الرسالة بشأن إلغاء الاشتراك بعد تغيير في الشروط (PDF، مجانًا)',
  'bills.telecom.pass.download_penalty_letter':
    'تنزيل الرسالة التي تطلب مراجعة الغرامة \u2068(PDF)\u2069',
  'bills.telecom.letters.title': 'رسالة يمكنك تنزيلها مجانًا',
  'bills.telecom.letters.text':
    'تُخبر هذه الرسالة مشغّلك متى أشعرك بالتغيير ومتى طلبت إلغاء الاشتراك، دون أرقام، وتُنزَّل مجانًا. وتُنشأ على جهازك.',
  'bills.telecom.letter.legend': 'بياناتك للرسائل (اختياري)',
  'bills.telecom.letter.company': 'المشغّل',
  'bills.telecom.letter.reference': 'رقم العميل أو العقد',
  'bills.telecom.letter.privacy':
    'لا تُستخدَم هذه البيانات إلا لملء الرسائل على جهازك؛ ولا تُرسَل ولا تُحفَظ.',
  'bills.pass.price':
    '4,99 € شاملًا ضريبة القيمة المضافة \u2068(IVA)\u2069. دفعة واحدة، دون حساب ولا اشتراك. يدوم التصريح 7 أيام ولا يصلح إلا في هذا المتصفح: خلال تلك المدة يمكنك قراءة ما يصل إلى 15 حزمة من المستندات، في أي قسم، وتنزيل التقرير مجددًا دون الدفع مرة أخرى. ويضيع إذا استخدمت جهازًا آخر أو نافذة خاصة، أو إذا حذفت بيانات التصفح.',
  'bills.basket.memory':
    'لا نحفظ شيئًا: سنتك لا توجد إلا في علامة التبويب هذه. إذا أغلقتها أو أعدت تحميلها، ارفع فواتيرك من جديد. إذا دفعت، تنتظر الفواتير التي راجعتها في علامة التبويب هذه بينما تكون في صفحة الدفع، وتعود كلها معك؛ أما المقروءة التي لم تراجعها بعد، فلا.',
