  'mortgage.title': 'مصاريف قرضك العقاري \u2068(hipoteca)\u2069 وعمولاته: ماذا يقول القانون',
  'mortgage.description':
    'أيّ مصاريف قرضك العقاري يحمّلها القانون للبنك، وأيّ توزيع تطبّقه المحكمة العليا \u2068(Tribunal Supremo)\u2069 على الصكوك السابقة لعام 2019، والحدود القصوى لعمولاته.',
  'mortgage.h1': 'مصاريف قرضك العقاري وعمولاته وبنوده',
  'mortgage.lead':
    'انطلاقًا من بيانات صكّك \u2068(escritura)\u2069 وفواتيرك: أيّ مصاريف تأسيس القرض العقاري يحمّلها القانون للبنك، وأيّ توزيع تطبّقه المحكمة العليا \u2068(Tribunal Supremo)\u2069 على الصكوك السابقة لعام 2019، وهل تجاوزت عمولةُ السداد المبكر أو التحوّل إلى سعر فائدة ثابت الحدَّ الأقصى القانوني، وماذا يقول القانون والمحاكم عن بنود صكّك. للقرض العقاري الذي يحصل عليه شخص على مسكنه.',
  'mortgage.beta': 'تجريبي',
  'mortgage.beta_note':
    'قسم قيد التجربة. الأرقام مستمدّة مما تكتبه ومن القانون؛ وما يتوقف على قاضٍ يُعرَض دائمًا على حدة.',
  'mortgage.no_js': 'تحتاج المراجعة إلى JavaScript. تُجرى كاملةً على جهازك، وما تكتبه لا يغادره.',
  'mortgage.reviewed': 'رُوجع في {fecha}',
  'mortgage.app_name': 'مراجعة مصاريف قرضك العقاري وعمولاته',
  'mortgage.guide.title': 'ماذا يقول القانون والمحاكم عن قرضك العقاري',
  'mortgage.guide.lead':
    'أيّ مصاريف تأسيس القرض العقاري يحمّلها القانون للبنك منذ 2019، وما الذي يتوقف على قاضٍ، وما الحدود القصوى لعمولات السداد المبكر أو التحوّل إلى سعر فائدة ثابت، وما الذي يلزم البنكَ أن يسلّمه لك قبل الصك، مع النص القانوني أو الحكم الذي يُستمَدّ منه كل أمر.',
  'mortgage.guide.sources': 'المصادر',
