  'mortgage.guide.table.copies': 'نُسخ الصك',
  'mortgage.guide.table.registry': 'تسجيل الرهن في السجل العقاري \u2068(registro)\u2069',
  'mortgage.guide.table.agency': 'مكتب الإجراءات الإدارية \u2068(gestoría)\u2069',
  'mortgage.guide.table.valuation': 'التقييم العقاري \u2068(tasación)\u2069',
