  'mortgage.documents.guide.lead':
    'قد يتكوّن صكّك من 25-60 صفحة. إذا كان لديك بصيغة PDF، فارفعه كاملًا: يُبحَث عن صفحاته المفيدة. وإذا صوّرته، فصوّر الصفحة الأولى، وصفحات البنود المالية (الفوائد، والعمولات، والمصاريف، والتأخير، والاستحقاق)، وفواتيرك.',
