  'client.credit.calculation.information.cash_price':
    'في الشراء الممَوَّل، يلزم أن يذكر العقد السلعة وسعرها نقدًا \u2068(art. 16.2)\u2069.',
  'client.credit.calculation.information.linked_credit':
    'إذا كان القرض لا يُستخدَم إلا لدفع ثمن شراء سلعة أو خدمة محدّدة ويشكّل مع ذلك الشراء وحدة واحدة، فهو ائتمان مرتبط \u2068(crédito vinculado)\u2069 \u2068(art. 29.1)\u2069. وعندئذٍ يلزم أن يذكر العقد السلعة وسعرها نقدًا \u2068(art. 16.2.e)\u2069؛ وإذا عدلت عن الشراء، يزول التزامك بالقرض دون غرامة \u2068(art. 29.2)\u2069؛ وإذا لم تصل السلعة أو لم تكن مطابقة، تسري تلك الحقوق في بعض الحالات تجاه المُقرِض أيضًا \u2068(art. 29.3)\u2069.',
  'client.credit.calculation.information.cash_option':
    'ويمكنك ألّا تموّل الشراء وأن تدفع ثمنه كما اتفقت مع البائع \u2068(art. 26.3)\u2069.',
  'client.credit.calculation.information.revolving_info':
    'ينص أمر الشفافية المصرفية \u2068(orden de transparencia bancaria)\u2069 على أن تقدّم بطاقة الائتمان المتجددة \u2068(revolving)\u2069 معلومات مرة كل ثلاثة أشهر على الأقل عن الدين، والسعر، والقسط، ومتى وبأي مبلغ تنتهي من سدادها \u2068(art. 33 quinquies)\u2069، وعلى أن يُقدَّم لك، إذا طلبت، خلال 5 أيام عمل رسمية ما دفعته وما عليك من دين، مع تفصيله، وجدول سداد \u2068(art. 33 sexies)\u2069. ولم يُتحقَّق من الجهات والعقود السابقة التي يشملها ذلك، ولذلك لا يُقال إن الجهة المانحة لبطاقتك ملزَمة به.',
