  'client.credit.report.intro':
    'يقارن هذا التقرير أرقام ائتمانك بما يقوله القانون، بندًا بندًا، بالبيانات التي أكّدتها في المراجعة: معدل الفائدة السنوي الفعلي \u2068(TAE)\u2069 الناتج عنها، وكيف يقارَن بمتوسط سعر الفائدة لدى البنك المركزي الإسباني \u2068(Banco de España)\u2069، والحد الأقصى لما يُحصَّل عند السداد المبكر، ومهلة العدول. وحيث تتوقف النتيجة على معلومة لا تعرفها، يعرض كل قراءة. يقدّم معلومات عن القانون وليس استشارة قانونية.',
